    #[cfg(feature = "slow-tests")]
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn independent_reads_do_not_inherit_an_unrelated_non_database_wait() {
        struct InstalledBarrier(RequestDispatchTestBarrier);

        impl Drop for InstalledBarrier {
            fn drop(&mut self) {
                self.0.release.notify_waiters();
                if let Ok(mut installed) = REQUEST_DISPATCH_TEST_BARRIER
                    .get_or_init(Default::default)
                    .lock()
                {
                    installed.take();
                }
            }
        }

        let token = uuid::Uuid::new_v4().to_string();
        let barrier = RequestDispatchTestBarrier {
            token: token.clone(),
            entered: Arc::new(Notify::new()),
            release: Arc::new(Notify::new()),
        };
        {
            let mut installed = REQUEST_DISPATCH_TEST_BARRIER
                .get_or_init(Default::default)
                .lock()
                .unwrap();
            assert!(installed.replace(barrier.clone()).is_none());
        }
        let installed_barrier = InstalledBarrier(barrier.clone());
        let root = std::env::temp_dir().canonicalize().unwrap().join(format!(
            "rovai-execution-page-dispatch-{}",
            uuid::Uuid::new_v4()
        ));
        let data_dir = root.join("data");
        let workspace_dir = root.join("workspace");
        fs::create_dir_all(&workspace_dir).unwrap();
        let runtime_camp_files_root =
            rovai_core::storage_layout::server_runtime_root(&data_dir).unwrap();
        let (service, runner) = embedded(
            CoreConfig {
                runtime_camp_files_root: runtime_camp_files_root.clone(),
                data_dir,
                skill_library_root: root.join("skills"),
                mcp_config_path: Some(root.join("mcp.json")),
                require_existing_authority: false,
                automation_scheduler_control: None,
                removed_skill_project_roots: RemovedSkillProjectRoots::default(),
            },
            Arc::new(RuntimeSearchEnvironment::for_test_paths(1, Vec::new())),
        )
        .unwrap();
        let mut runner_task = tokio::spawn(runner.run());
        tokio::time::timeout(Duration::from_secs(20), service.wait_ready())
            .await
            .expect("isolated Core should become ready")
            .unwrap();

        let blocked_service = service.clone();
        let blocked_request = tokio::spawn(async move {
            blocked_service
                .request("test.requestDispatchBarrier", json!({ "token": token }))
                .await
        });
        tokio::time::timeout(Duration::from_secs(5), barrier.entered.notified())
            .await
            .expect("the unrelated ordered request should reach its controlled barrier");

        let page_service = service.clone();
        let mut page_request = tokio::spawn(async move {
            page_service
                .request(
                    "agentRunExecution.page",
                    json!({
                        "campId": "rvcamp_dispatch_test",
                        "agentRunId": "run-dispatch-test",
                        "beforeSequence": null,
                        "limit": 24
                    }),
                )
                .await
        });
        let inspection_service = service.clone();
        let mut inspection_request = tokio::spawn(async move {
            inspection_service
                .request(
                    "workspaces.inspect",
                    json!({ "path": workspace_dir.to_str().unwrap() }),
                )
                .await
        });
        let barrier_release_at = tokio::time::Instant::now() + Duration::from_secs(3);
        let page_before_release =
            tokio::time::timeout_at(barrier_release_at, &mut page_request).await;
        let page_finished_while_blocked = page_before_release.is_ok();
        let inspection_before_release =
            tokio::time::timeout_at(barrier_release_at, &mut inspection_request).await;
        let inspection_finished_while_blocked = inspection_before_release.is_ok();

        tokio::time::sleep_until(barrier_release_at).await;
        barrier.release.notify_waiters();
        let _ = blocked_request.await;
        let page_reply = match page_before_release {
            Ok(completed) => completed.unwrap().unwrap(),
            Err(_) => page_request.await.unwrap().unwrap(),
        };
        let inspection_reply = match inspection_before_release {
            Ok(completed) => completed.unwrap().unwrap(),
            Err(_) => inspection_request.await.unwrap().unwrap(),
        };
        drop(service);
        if tokio::time::timeout(Duration::from_secs(10), &mut runner_task)
            .await
            .is_err()
        {
            runner_task.abort();
            let _ = runner_task.await;
        }
        drop(installed_barrier);
        #[cfg(unix)]
        if runtime_camp_files_root.join("camps").exists() {
            use std::os::unix::fs::PermissionsExt;
            fs::set_permissions(
                runtime_camp_files_root.join("camps"),
                fs::Permissions::from_mode(0o700),
            )
            .unwrap();
        }
        if let Err(error) = fs::remove_dir_all(&root) {
            eprintln!("isolated dispatch fixture cleanup deferred: {error}");
        }

        assert!(
            page_finished_while_blocked,
            "a cold execution page waited for unrelated non-database work"
        );
        assert_eq!(
            page_reply
                .error
                .as_ref()
                .and_then(|error| error.get("code")),
            Some(&json!("CORE_REQUEST_FAILED")),
            "the nonexistent Run should still reach the ordinary execution-page validation"
        );
        assert!(
            inspection_finished_while_blocked,
            "workspace inspection waited for unrelated non-database work"
        );
        assert!(
            inspection_reply.error.is_none(),
            "the independent workspace inspection should succeed: {:?}",
            inspection_reply.error
        );
    }

    #[cfg(feature = "slow-tests")]
    #[tokio::test(flavor = "multi_thread", worker_threads = 4)]
    async fn mission_git_reads_release_ingress_database_and_lifecycle_authority() {
        use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};

        struct InstalledMissionGitBarrier(MissionGitReadTestBarrier);
        impl InstalledMissionGitBarrier {
            fn release(&self) {
                self.0.released.store(true, Ordering::SeqCst);
                self.0.release.notify_waiters();
            }
        }
        impl Drop for InstalledMissionGitBarrier {
            fn drop(&mut self) {
                self.release();
                if let Ok(mut installed) = MISSION_GIT_READ_TEST_BARRIER
                    .get_or_init(Default::default)
                    .lock()
                {
                    installed.take();
                }
            }
        }
        fn install_barrier(mission_id: &str, method: &str) -> InstalledMissionGitBarrier {
            let barrier = MissionGitReadTestBarrier {
                mission_id: mission_id.to_string(),
                method: method.to_string(),
                entered_count: Arc::new(AtomicUsize::new(0)),
                entered: Arc::new(Notify::new()),
                released: Arc::new(AtomicBool::new(false)),
                release: Arc::new(Notify::new()),
            };
            let mut installed = MISSION_GIT_READ_TEST_BARRIER
                .get_or_init(Default::default)
                .lock()
                .unwrap();
            assert!(installed.replace(barrier.clone()).is_none());
            InstalledMissionGitBarrier(barrier)
        }
        async fn wait_for_entries(barrier: &MissionGitReadTestBarrier, count: usize) {
            tokio::time::timeout(Duration::from_secs(5), async {
                while barrier.entered_count.load(Ordering::SeqCst) < count {
                    let entered = barrier.entered.notified();
                    if barrier.entered_count.load(Ordering::SeqCst) >= count {
                        break;
                    }
                    entered.await;
                }
            })
            .await
            .expect("Mission Git reads should reach the controlled Git barrier");
        }
        fn spawn_requests(
            service: &CoreService,
            method: &str,
            params: Value,
            count: usize,
        ) -> Vec<tokio::task::JoinHandle<Result<CoreReply>>> {
            (0..count)
                .map(|_| {
                    let service = service.clone();
                    let method = method.to_string();
                    let params = params.clone();
                    tokio::spawn(async move { service.request(&method, params).await })
                })
                .collect()
        }
        async fn replies(
            requests: Vec<tokio::task::JoinHandle<Result<CoreReply>>>,
        ) -> Vec<CoreReply> {
            let mut replies = Vec::new();
            for request in requests {
                replies.push(request.await.unwrap().unwrap());
            }
            replies
        }
        async fn assert_ordinary_reads_finish(
            service: &CoreService,
            camp_id: &str,
            agent_run_id: &str,
            evidence_id: &str,
            expected_output: &str,
        ) {
            let open_service = service.clone();
            let event_service = service.clone();
            let page_service = service.clone();
            let content_service = service.clone();
            let camp_id_for_open = camp_id.to_string();
            let camp_id_for_events = camp_id.to_string();
            let camp_id_for_page = camp_id.to_string();
            let camp_id_for_content = camp_id.to_string();
            let run_id = agent_run_id.to_string();
            let evidence_id = evidence_id.to_string();
            let (open, events, page, content) =
                tokio::time::timeout(Duration::from_secs(5), async move {
                    tokio::join!(
                        open_service.request(
                            "camps.open",
                            json!({
                                "traceId": uuid::Uuid::new_v4().to_string(),
                                "campId": camp_id_for_open,
                            }),
                        ),
                        event_service.request(
                            "events.subscribe",
                            json!({
                                "campId": camp_id_for_events,
                                "afterGlobalSequence": 0,
                                "limit": 50,
                            }),
                        ),
                        page_service.request(
                            "agentRunExecution.page",
                            json!({
                                "campId": camp_id_for_page,
                                "agentRunId": run_id,
                                "beforeSequence": null,
                                "afterSequence": null,
                                "limit": 24,
                            }),
                        ),
                        content_service.request(
                            "agentRunEvidence.getContent",
                            json!({
                                "campId": camp_id_for_content,
                                "evidenceId": evidence_id,
                            }),
                        ),
                    )
                })
                .await
                .expect("ordinary reads must finish before Mission Git is released");
            let replies = [
                open.unwrap(),
                events.unwrap(),
                page.unwrap(),
                content.unwrap(),
            ];
            for reply in &replies {
                assert!(
                    reply.error.is_none(),
                    "ordinary read failed: {:?}",
                    reply.error
                );
            }
            assert_eq!(
                replies[3].result.as_ref().unwrap()["payload"]["item"]["aggregatedOutput"],
                expected_output,
                "getContent must return the full managed Blob while Mission Git is blocked"
            );
        }
        fn assert_refresh_required(reply: &CoreReply) {
            let message = reply
                .error
                .as_ref()
                .and_then(|error| error.get("message"))
                .and_then(Value::as_str)
                .unwrap_or_default();
            assert!(
                message.contains("mission.changes_refresh_required"),
                "expected a recoverable Mission view error, got {message:?}"
            );
        }

        let root = std::env::temp_dir().canonicalize().unwrap().join(format!(
            "rovai-mission-git-dispatch-{}",
            uuid::Uuid::new_v4()
        ));
        fs::create_dir_all(&root).unwrap();
        let root = fs::canonicalize(&root).unwrap();
        let source = root.join("source");
        fs::create_dir_all(&source).unwrap();
        let git_path = crate::runtime_discovery::resolve_active_command_path("git")
            .expect("Git is required for the real Mission dispatch test");
        let git = |arguments: &[&str]| {
            let output = std::process::Command::new(&git_path)
                .arg("-C")
                .arg(&source)
                .args(arguments)
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "Git fixture command failed: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        };
        git(&["init", "-b", "main"]);
        git(&["config", "user.name", "Mission Dispatch Test"]);
        git(&["config", "user.email", "mission-dispatch@example.invalid"]);
        fs::write(source.join("tracked.txt"), "base\n").unwrap();
        git(&["add", "tracked.txt"]);
        git(&["commit", "-m", "base"]);

        let data_dir = root.join("data");
        fs::create_dir_all(&data_dir).unwrap();
        let runtime_camp_files_root =
            rovai_core::storage_layout::server_runtime_root(&data_dir).unwrap();
        let attachment_views =
            CampAttachmentViewStore::admit(&runtime_camp_files_root, &data_dir, &[]).unwrap();
        let mut database = Database::open_with_runtime_camp_files_root(
            &data_dir,
            attachment_views.root(),
            attachment_views.root_identity_digest(),
        )
        .unwrap();
        let agent_id = AgentProfileService::default()
            .list_profiles(&database)
            .unwrap()
            .into_iter()
            .next()
            .expect("the startup database should include a default member")
            .agent_id;
        rovai_core::agent_profile::configure_test_runtime(&database, &[agent_id.as_str()]);
        let created = crate::mission::MissionService::default()
            .create(
                &mut database,
                &CommandEnvelope {
                    command_id: uuid::Uuid::new_v4().to_string(),
                    actor: ActorRef::User {
                        user_id: "test-user".into(),
                    },
                    camp_id: None,
                    expected_versions: Vec::new(),
                    execution_epoch: None,
                    payload: crate::mission::CreateMissionCommand {
                        title: "Mission Git background dispatch".into(),
                        description: String::new(),
                        project_path: source.to_string_lossy().into_owned(),
                        project_binding_kind: ProjectBindingKind::Directory,
                        member_agent_ids: vec![agent_id.clone()],
                        default_lead_agent_id: agent_id.clone(),
                        tags: Vec::new(),
                        source_attachments: Vec::new(),
                    },
                },
            )
            .unwrap();
        let mission_id = created.result.payload["missionId"]
            .as_str()
            .unwrap()
            .to_string();
        let camp_id = created.result.payload["campId"]
            .as_str()
            .unwrap()
            .to_string();
        attachment_views
            .ensure_empty_camp_ready(&mut database, &camp_id)
            .unwrap();
        let execution_host_id: String = database
            .connection()
            .query_row(
                "SELECT id FROM mission_execution_host WHERE singleton=1",
                [],
                |row| row.get(0),
            )
            .unwrap();
        let sent = CollaborationService::default()
            .send_test_camp_message(
                &mut database,
                &CommandEnvelope {
                    command_id: uuid::Uuid::new_v4().to_string(),
                    actor: ActorRef::User {
                        user_id: "test-user".into(),
                    },
                    camp_id: Some(camp_id.clone()),
                    expected_versions: Vec::new(),
                    execution_epoch: None,
                    payload: rovai_core::collaboration::TestCampMessageCommand {
                        camp_id: camp_id.clone(),
                        draft_revision: None,
                        body: "Create a real execution window".into(),
                        prepared_attachment_ids: Vec::new(),
                        address: rovai_core::collaboration::TestCampMessageAddress::Default,
                        reply_to_camp_message_id: None,
                        execution: Some(ExecutionRequest {
                            task_id: None,
                            purpose: "Mission Git queue verification".into(),
                            completion_role: "required".into(),
                            budget: None,
                        }),
                    },
                },
            )
            .unwrap();
        let agent_run_id = sent.result.payload["agentRunIds"][0]
            .as_str()
            .unwrap()
            .to_string();
        database
            .connection()
            .execute(
                "UPDATE agent_run SET status='running',execution_epoch=1 WHERE id=?1",
                [&agent_run_id],
            )
            .unwrap();
        let secret = format!("MISSION_GIT_BLOB_{}", "x".repeat(573_647));
        ExecutionEvidenceService
            .record_runtime_event(
                &mut database,
                &ManagedBlobStore::new(&data_dir),
                &agent_run_id,
                1,
                "activity.started",
                &json!({
                    "item": {
                        "id": "command-1",
                        "type": "commandExecution",
                        "command": "git status",
                        "status": "inProgress",
                    }
                }),
            )
            .unwrap()
            .unwrap();
        let evidence = ExecutionEvidenceService
            .record_runtime_event(
                &mut database,
                &ManagedBlobStore::new(&data_dir),
                &agent_run_id,
                1,
                "activity.completed",
                &json!({
                    "item": {
                        "id": "command-1",
                        "type": "commandExecution",
                        "command": "git status",
                        "status": "completed",
                        "exitCode": 0,
                        "aggregatedOutput": secret.clone(),
                    }
                }),
            )
            .unwrap()
            .unwrap();
        assert!(evidence.is_truncated && evidence.content_blob_id.is_some());
        let evidence_id = evidence.id.clone();

        let mission_git = crate::mission_workspace::MissionGit::new(git_path.clone()).unwrap();
        let repository = mission_git.inspect(&source).await.unwrap().unwrap();
        let worktree = root.join("mission-worktree");
        let mut workspace = crate::mission_workspace::MissionWorkspace {
            id: uuid::Uuid::new_v4().to_string(),
            mission_id: mission_id.clone(),
            camp_id: camp_id.clone(),
            execution_host_id,
            source_directory: source.to_string_lossy().into_owned(),
            repository_root: repository.root.to_string_lossy().into_owned(),
            git_common_dir: repository.common_dir.to_string_lossy().into_owned(),
            worktree_path: worktree.to_string_lossy().into_owned(),
            working_directory: worktree.to_string_lossy().into_owned(),
            base_branch: repository.base_branch,
            branch: format!("rovai/mission/dispatch-{}", uuid::Uuid::new_v4()),
            base_sha: repository.base_sha,
            preparation_token: uuid::Uuid::new_v4().to_string(),
            preparation_kind: "create".into(),
            generation: 1,
            state: "preparing".into(),
            cleanup_command_id: None,
            cleanup_expected_branch_oid: None,
            cleanup_worktree_removed: false,
            cleanup_branch_removed: false,
            diagnostic: None,
        };
        crate::mission_workspace::persist_plan(database.connection(), &workspace).unwrap();
        drop(database);
        mission_git.materialize(&workspace).await.unwrap();
        workspace.state = "ready".into();
        fs::write(worktree.join("tracked.txt"), "changed\n").unwrap();
        let database = Database::open_with_runtime_camp_files_root(
            &data_dir,
            attachment_views.root(),
            attachment_views.root_identity_digest(),
        )
        .unwrap();
        database
            .connection()
            .execute(
                "UPDATE mission_workspace SET state='ready' WHERE id=?1",
                [&workspace.id],
            )
            .unwrap();
        let database_path = database.path().to_path_buf();
        drop(database);
        drop(attachment_views);
        let mut search_paths = vec![git_path.parent().unwrap().to_path_buf()];
        search_paths.extend(std::env::split_paths(
            &std::env::var_os("PATH").unwrap_or_default(),
        ));
        let (service, runner) = embedded(
            CoreConfig {
                runtime_camp_files_root: runtime_camp_files_root.clone(),
                data_dir: data_dir.clone(),
                skill_library_root: root.join("skills"),
                mcp_config_path: Some(root.join("mcp.json")),
                require_existing_authority: false,
                automation_scheduler_control: None,
                removed_skill_project_roots: RemovedSkillProjectRoots::default(),
            },
            Arc::new(RuntimeSearchEnvironment::for_test_paths(1, search_paths)),
        )
        .unwrap();
        let mut runner_task = tokio::spawn(runner.run());
        tokio::time::timeout(Duration::from_secs(20), service.wait_ready())
            .await
            .expect("isolated Core should become ready")
            .unwrap();

        let changes_barrier = install_barrier(&mission_id, "missions.changes");
        let changes_requests = spawn_requests(
            &service,
            "missions.changes",
            json!({ "missionId": mission_id }),
            MISSION_GIT_READ_CONCURRENCY_LIMIT + 1,
        );
        wait_for_entries(&changes_barrier.0, MISSION_GIT_READ_CONCURRENCY_LIMIT).await;
        tokio::time::sleep(Duration::from_millis(100)).await;
        assert_eq!(
            changes_barrier.0.entered_count.load(Ordering::SeqCst),
            MISSION_GIT_READ_CONCURRENCY_LIMIT,
            "the extra Mission change read must wait at the bounded permit"
        );
        assert!(!changes_requests.last().unwrap().is_finished());
        assert_ordinary_reads_finish(&service, &camp_id, &agent_run_id, &evidence_id, &secret)
            .await;
        changes_barrier.release();
        let change_replies = replies(changes_requests).await;
        drop(changes_barrier);
        for reply in &change_replies {
            assert!(
                reply.error.is_none(),
                "Mission changes failed: {:?}",
                reply.error
            );
        }
        let view_id = change_replies[0].result.as_ref().unwrap()["viewId"]
            .as_str()
            .unwrap()
            .to_string();
        let file_id = change_replies[0].result.as_ref().unwrap()["files"][0]["id"]
            .as_str()
            .unwrap()
            .to_string();

        let diff_barrier = install_barrier(&mission_id, "missions.fileDiff");
        let diff_requests = spawn_requests(
            &service,
            "missions.fileDiff",
            json!({ "missionId": mission_id, "viewId": view_id, "fileId": file_id }),
            MISSION_GIT_READ_CONCURRENCY_LIMIT + 1,
        );
        wait_for_entries(&diff_barrier.0, MISSION_GIT_READ_CONCURRENCY_LIMIT).await;
        tokio::time::sleep(Duration::from_millis(100)).await;
        assert_eq!(
            diff_barrier.0.entered_count.load(Ordering::SeqCst),
            MISSION_GIT_READ_CONCURRENCY_LIMIT,
            "the extra Mission file Diff must wait at the bounded permit"
        );
        assert!(!diff_requests.last().unwrap().is_finished());
        assert_ordinary_reads_finish(&service, &camp_id, &agent_run_id, &evidence_id, &secret)
            .await;
        diff_barrier.release();
        let diff_replies = replies(diff_requests).await;
        drop(diff_barrier);
        for reply in &diff_replies {
            assert!(
                reply.error.is_none(),
                "Mission file Diff failed: {:?}",
                reply.error
            );
        }

        let stale_changes_barrier = install_barrier(&mission_id, "missions.changes");
        let mut stale_changes = spawn_requests(
            &service,
            "missions.changes",
            json!({ "missionId": mission_id }),
            1,
        );
        wait_for_entries(&stale_changes_barrier.0, 1).await;
        let lifecycle = rusqlite::Connection::open(&database_path).unwrap();
        lifecycle
            .execute(
                "UPDATE mission_workspace SET state='cleanup_pending',generation=generation+1 WHERE id=?1",
                [&workspace.id],
            )
            .expect("cleanup must acquire SQLite while the Git read is blocked");
        stale_changes_barrier.release();
        let stale_changes_reply = stale_changes.remove(0).await.unwrap().unwrap();
        drop(stale_changes_barrier);
        assert_refresh_required(&stale_changes_reply);
        lifecycle
            .execute(
                "UPDATE mission_workspace SET state='ready' WHERE id=?1",
                [&workspace.id],
            )
            .unwrap();
        let refreshed = service
            .request("missions.changes", json!({ "missionId": mission_id }))
            .await
            .unwrap();
        assert!(
            refreshed.error.is_none(),
            "refresh failed: {:?}",
            refreshed.error
        );
        let refreshed_view_id = refreshed.result.as_ref().unwrap()["viewId"]
            .as_str()
            .unwrap()
            .to_string();
        let refreshed_file_id = refreshed.result.as_ref().unwrap()["files"][0]["id"]
            .as_str()
            .unwrap()
            .to_string();

        let stale_diff_barrier = install_barrier(&mission_id, "missions.fileDiff");
        let mut stale_diff = spawn_requests(
            &service,
            "missions.fileDiff",
            json!({
                "missionId": mission_id,
                "viewId": refreshed_view_id,
                "fileId": refreshed_file_id,
            }),
            1,
        );
        wait_for_entries(&stale_diff_barrier.0, 1).await;
        lifecycle
            .execute(
                "UPDATE mission_workspace SET state='cleanup_pending',generation=generation+1 WHERE id=?1",
                [&workspace.id],
            )
            .expect("rebuild must acquire SQLite while the file Diff is blocked");
        stale_diff_barrier.release();
        let stale_diff_reply = stale_diff.remove(0).await.unwrap().unwrap();
        drop(stale_diff_barrier);
        assert_refresh_required(&stale_diff_reply);
        lifecycle
            .execute(
                "UPDATE mission_workspace SET state='ready' WHERE id=?1",
                [&workspace.id],
            )
            .unwrap();
        let invalidated_view = service
            .request(
                "missions.fileDiff",
                json!({
                    "missionId": mission_id,
                    "viewId": refreshed_view_id,
                    "fileId": refreshed_file_id,
                }),
            )
            .await
            .unwrap();
        assert_refresh_required(&invalidated_view);
        drop(lifecycle);

        rusqlite::Connection::open(&database_path)
            .unwrap()
            .execute(
                "UPDATE agent_run SET status='succeeded',ended_at=?2 WHERE id=?1",
                rusqlite::params![&agent_run_id, chrono::Utc::now().to_rfc3339()],
            )
            .unwrap();

        let staged = std::process::Command::new(&git_path)
            .arg("-C")
            .arg(&worktree)
            .args(["add", "tracked.txt"])
            .output()
            .unwrap();
        assert!(
            staged.status.success(),
            "failed to stage the cleanup fixture: {}",
            String::from_utf8_lossy(&staged.stderr)
        );
        fs::write(worktree.join("tracked.txt"), "unstaged after staged\n").unwrap();
        fs::write(worktree.join("untracked.txt"), "untracked\n").unwrap();
        let cleanup = service
            .request(
                "missions.workspace.cleanup",
                json!({
                    "commandId": uuid::Uuid::new_v4().to_string(),
                    "command": { "missionId": mission_id },
                }),
            )
            .await
            .unwrap();
        assert!(
            cleanup.error.is_none(),
            "cleanup admission failed before the worker could run: {:?}",
            cleanup.error
        );
        assert_eq!(cleanup.result.as_ref().unwrap()["status"], "applied");
        assert_eq!(
            cleanup.result.as_ref().unwrap()["payload"]["scheduled"],
            true
        );
        tokio::time::timeout(Duration::from_secs(20), async {
            loop {
                let cleanup_state = rusqlite::Connection::open(&database_path)
                    .unwrap()
                    .query_row(
                        "SELECT state,diagnostic,cleanup_expected_branch_oid,cleanup_worktree_removed,cleanup_branch_removed FROM mission_workspace WHERE id=?1",
                        [&workspace.id],
                        |row| {
                            Ok((
                                row.get::<_, String>(0)?,
                                row.get::<_, Option<String>>(1)?,
                                row.get::<_, Option<String>>(2)?,
                                row.get::<_, bool>(3)?,
                                row.get::<_, bool>(4)?,
                            ))
                        },
                    )
                    .unwrap();
                if cleanup_state.0 == "ready"
                    && cleanup_state.1.as_deref() == Some("mission.workspace_dirty")
                {
                    assert_eq!(cleanup_state.2, None);
                    assert!(!cleanup_state.3 && !cleanup_state.4);
                    break;
                }
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .expect("a reliable dirty refusal must restore the complete workspace to ready");
        assert_eq!(
            fs::read_to_string(worktree.join("tracked.txt")).unwrap(),
            "unstaged after staged\n"
        );
        assert_eq!(
            fs::read_to_string(worktree.join("untracked.txt")).unwrap(),
            "untracked\n"
        );
        let readable_after_refusal = service
            .request("missions.changes", json!({ "missionId": mission_id }))
            .await
            .unwrap();
        assert!(
            readable_after_refusal.error.is_none(),
            "a non-destructive refusal must not permanently block Mission reads: {:?}",
            readable_after_refusal.error
        );

        drop(service);
        if tokio::time::timeout(Duration::from_secs(10), &mut runner_task)
            .await
            .is_err()
        {
            runner_task.abort();
            let _ = runner_task.await;
        }
        CampAttachmentStore::new(&data_dir)
            .remove_camp(&camp_id)
            .unwrap();
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt;
            let view_attachment_root = runtime_camp_files_root
                .join("camps")
                .join(&camp_id)
                .join("attachments");
            for directory in [
                view_attachment_root.as_path(),
                view_attachment_root.parent().unwrap(),
                view_attachment_root.parent().unwrap().parent().unwrap(),
            ] {
                if directory.exists() {
                    fs::set_permissions(directory, fs::Permissions::from_mode(0o700)).unwrap();
                }
            }
        }
        fs::remove_dir_all(&root).unwrap();
    }

    #[test]
    fn navigation_invalidation_covers_projection_writes_but_not_reads() {
        for method in [
            "members.update",
            "members.remove",
            "navigation.campViewed",
            "camps.create",
            "camps.rename",
            "camps.enter",
            "camps.delete",
            "camp.messages.send",
            "camp.messages.withdraw",
            "userAutomation.camp.send",
            "agentRuns.cancel",
        ] {
            assert!(request_invalidates_navigation(method), "{method}");
        }
        for method in [
            "navigation.snapshot",
            "navigation.groupCamps",
            "navigation.findCamp",
            "camps.open",
            "camp.messages.page",
            "health.check",
        ] {
            assert!(!request_invalidates_navigation(method), "{method}");
        }
        for method in [
            "camps.create",
            "camps.discardPending",
            "camp.messages.send",
            "camp.messages.withdraw",
        ] {
            assert!(
                navigation_invalidation_emitted_at_commit_boundary(method),
                "{method}"
            );
        }
        assert!(!navigation_invalidation_emitted_at_commit_boundary(
            "camps.rename"
        ));
    }

    #[test]
    fn navigation_invalidation_skips_rejected_commands_and_preserves_camp_scope() {
        assert!(navigation_mutation_was_rejected(
            &json!({ "status": "rejected" })
        ));
        assert!(navigation_mutation_was_rejected(&json!({
            "commandResult": { "status": "rejected" }
        })));
        assert!(!navigation_mutation_was_rejected(
            &json!({ "status": "applied" })
        ));
        assert_eq!(
            navigation_request_camp_id(&json!({
                "command": { "campId": "rvcamp_test" }
            })),
            Some("rvcamp_test")
        );

        let (output, mut receiver) = mpsc::unbounded_channel();
        emit_agent_run_terminal(
            &output,
            Some("rvcamp_test"),
            json!({ "agentRunId": "run-test" }),
        );
        let terminal: Value = serde_json::from_str(&receiver.try_recv().unwrap()).unwrap();
        assert_eq!(terminal["method"], "agent_run.terminal");
        assert_eq!(terminal["params"]["agentRunId"], "run-test");
        let invalidation: Value = serde_json::from_str(&receiver.try_recv().unwrap()).unwrap();
        assert_eq!(invalidation["method"], "navigation.invalidated");
        assert_eq!(invalidation["params"]["reason"], "agent_run.terminal");
        assert_eq!(invalidation["params"]["campId"], "rvcamp_test");
    }

    #[cfg(all(target_os = "macos", feature = "slow-tests"))]
    #[tokio::test]
    async fn late_mission_preparation_cannot_erase_camp_deletion_cleanup_owner() {
        let root = std::env::temp_dir().canonicalize().unwrap().join(format!(
            "rovai-camp-delete-mission-race-{}",
            uuid::Uuid::new_v4()
        ));
        let source = root.join("source");
        fs::create_dir_all(&source).unwrap();
        let root = fs::canonicalize(&root).unwrap();
        let source = fs::canonicalize(&source).unwrap();
        let git_path = crate::runtime_discovery::resolve_active_command_path("git")
            .expect("Git is required for the Mission deletion race regression");
        let git = |arguments: &[&str]| {
            let output = std::process::Command::new(&git_path)
                .arg("-C")
                .arg(&source)
                .args(arguments)
                .output()
                .unwrap();
            assert!(
                output.status.success(),
                "Git fixture command failed: {}",
                String::from_utf8_lossy(&output.stderr)
            );
        };
        git(&["init", "-b", "main"]);
        git(&["config", "user.name", "Mission Deletion Race Test"]);
        git(&[
            "config",
            "user.email",
            "mission-deletion-race@example.invalid",
        ]);
        fs::write(source.join("tracked.txt"), "base\n").unwrap();
        git(&["add", "tracked.txt"]);
        git(&["commit", "-m", "base"]);

        let core = Arc::new(runtime_resolution_test_core(&root).unwrap());
        *core.runtime_search_environment.write().await =
            Arc::new(RuntimeSearchEnvironment::for_test_paths(
                2,
                vec![git_path.parent().unwrap().to_path_buf()],
            ));
        let (camp_id, candidate) = {
            let mut database = core.database.lock().await;
            let agent_id = AgentProfileService::default()
                .list_profiles(&database)
                .unwrap()
                .into_iter()
                .next()
                .expect("the startup database should include a default member")
                .agent_id;
            rovai_core::agent_profile::configure_test_runtime(&database, &[agent_id.as_str()]);
            let created = crate::mission::MissionService::default()
                .create(
                    &mut database,
                    &CommandEnvelope {
                        command_id: uuid::Uuid::new_v4().to_string(),
                        actor: ActorRef::User {
                            user_id: "test-user".into(),
                        },
                        camp_id: None,
                        expected_versions: Vec::new(),
                        execution_epoch: None,
                        payload: crate::mission::CreateMissionCommand {
                            title: "Camp deletion Mission race".into(),
                            description: String::new(),
                            project_path: source.to_string_lossy().into_owned(),
                            project_binding_kind: ProjectBindingKind::Directory,
                            member_agent_ids: vec![agent_id.clone()],
                            default_lead_agent_id: agent_id,
                            tags: Vec::new(),
                            source_attachments: Vec::new(),
                        },
                    },
                )
                .unwrap();
            let mission_id = created.result.payload["missionId"]
                .as_str()
                .unwrap()
                .to_string();
            let camp_id = created.result.payload["campId"]
                .as_str()
                .unwrap()
                .to_string();
            core.attachment_views
                .ensure_empty_camp_ready(&mut database, &camp_id)
                .unwrap();
            let started = crate::mission::MissionService::default()
                .start(
                    &mut database,
                    &CommandEnvelope {
                        command_id: uuid::Uuid::new_v4().to_string(),
                        actor: ActorRef::User {
                            user_id: "test-user".into(),
                        },
                        camp_id: Some(camp_id.clone()),
                        expected_versions: Vec::new(),
                        execution_epoch: None,
                        payload: crate::mission::StartMissionCommand { mission_id },
                    },
                )
                .unwrap();
            assert_eq!(started.result.status, CommandResultStatus::Accepted);
            let agent_run_id = claim_waiting_delivery_batches(&mut database, 1)
                .unwrap()
                .into_iter()
                .next()
                .expect("Mission start should create a dispatchable AgentRun");
            let candidate = ExecutionRuntimeService::default()
                .load_dispatchable_agent_run(&database, &agent_run_id)
                .unwrap()
                .expect("Mission AgentRun should be dispatchable");
            (camp_id, candidate)
        };

        let prepared = core
            .prepare_mission_workspace(&candidate)
            .await
            .unwrap()
            .expect("initial Mission workspace preparation should succeed");
        let worktree = PathBuf::from(&prepared.execution_root);
        assert!(worktree.exists());

        let wrapper_root = root.join("blocking-git");
        fs::create_dir_all(&wrapper_root).unwrap();
        let entered = wrapper_root.join("entered");
        let release = wrapper_root.join("release");
        let invocations = wrapper_root.join("invocations");
        let quote = |path: &Path| path.to_string_lossy().replace('\'', "'\\''");
        write_runtime_resolution_executable(
            &wrapper_root.join("git"),
            &format!(
                "#!/bin/sh\nprintf '%s\\n' \"$*\" >> '{}'\nfor argument in \"$@\"; do\n  if [ \"$argument\" = \"--show-toplevel\" ]; then\n    : > '{}'\n    while [ ! -e '{}' ]; do /bin/sleep 0.01; done\n    break\n  fi\ndone\nexec '{}' \"$@\"\n",
                quote(&invocations),
                quote(&entered),
                quote(&release),
                quote(&git_path),
            ),
        );
        *core.runtime_search_environment.write().await = Arc::new(
            RuntimeSearchEnvironment::for_test_paths(3, vec![wrapper_root.clone()]),
        );

        let prepare_task = tokio::spawn({
            let core = core.clone();
            let candidate = candidate.clone();
            async move { core.prepare_mission_workspace(&candidate).await }
        });
        tokio::time::timeout(Duration::from_secs(10), async {
            while !entered.exists() {
                tokio::time::sleep(Duration::from_millis(10)).await;
            }
        })
        .await
        .expect("late preparation did not reach the controlled Git validation");
        let blocked_invocation_count = fs::read_to_string(&invocations).unwrap().lines().count();

        let operation_id = uuid::Uuid::new_v4().to_string();
        let cleanup = {
            let mut database = core.database.lock().await;
            let version = database
                .connection()
                .query_row("SELECT version FROM camp WHERE id=?1", [&camp_id], |row| {
                    row.get::<_, i64>(0)
                })
                .unwrap();
            let accepted = CampDeletionService::default()
                .accept(
                    &mut database,
                    &CommandEnvelope {
                        command_id: operation_id.clone(),
                        actor: ActorRef::User {
                            user_id: "test-user".into(),
                        },
                        camp_id: Some(camp_id.clone()),
                        expected_versions: Vec::new(),
                        execution_epoch: None,
                        payload: DeleteCampCommand {
                            camp_id: camp_id.clone(),
                            expected_version: version,
                            force: true,
                            workspace_disposition:
                                rovai_core::collaboration::MissionWorkspaceDisposition::Cleanup,
                        },
                    },
                )
                .unwrap();
            assert_eq!(accepted.result.status, CommandResultStatus::Accepted);
            assert_eq!(accepted.result.payload["workspaceCleanupScheduled"], true);
            let cleanup = core
                .attachment_views
                .prepare_camp_delete_cleanup(&mut database, &camp_id, &operation_id)
                .unwrap()
                .expect("Camp deletion should prepare its resource handoff");
            let deletion = CampDeletionService::default()
                .due_camps(&database, 1)
                .unwrap()
                .into_iter()
                .next()
                .expect("accepted Camp deletion should be due");
            CampDeletionService::default()
                .commit_business_delete(&mut database, &core.attachment_views, &deletion, &cleanup)
                .unwrap();
            cleanup
        };

        {
            let database = core.database.lock().await;
            database
                .connection()
                .execute(
                    "UPDATE mission_workspace SET cleanup_command_id=NULL WHERE camp_id=?1",
                    [&camp_id],
                )
                .unwrap();
        }
        let missing_owner = core
            .finish_background_camp_deletion_cleanup(&cleanup)
            .await
            .expect_err("a promised Mission cleanup must not complete with an empty owner set");
        assert!(format!("{missing_owner:#}").contains("mission_workspace_cleanup_owner_missing"));
        {
            let database = core.database.lock().await;
            database
                .connection()
                .execute(
                    "UPDATE mission_workspace SET cleanup_command_id=?2 WHERE camp_id=?1",
                    rusqlite::params![camp_id, operation_id],
                )
                .unwrap();
        }

        let cleanup_task = tokio::spawn({
            let core = core.clone();
            let camp_id = camp_id.clone();
            async move { core.cleanup_mission_workspaces_locked(Some(&camp_id)).await }
        });
        tokio::time::sleep(Duration::from_millis(100)).await;
        assert_eq!(
            fs::read_to_string(&invocations).unwrap().lines().count(),
            blocked_invocation_count,
            "destructive Mission cleanup crossed the in-flight preparation lifecycle gate"
        );
        assert!(worktree.exists());
        assert!(
            !core
                .finish_background_camp_deletion_cleanup(&cleanup)
                .await
                .unwrap(),
            "the cleanup journal completed before Mission resources were removed"
        );

        fs::write(&release, "release\n").unwrap();
        let late_preparation = prepare_task
            .await
            .expect("late preparation task panicked")
            .unwrap();
        assert!(
            late_preparation.is_none(),
            "a preparation started before deletion returned a runnable workspace"
        );
        cleanup_task
            .await
            .expect("Mission cleanup task panicked")
            .unwrap();

        {
            let database = core.database.lock().await;
            let cleanup_state = database
                .connection()
                .query_row(
                    "SELECT state,cleanup_command_id,cleanup_worktree_removed,cleanup_branch_removed FROM mission_workspace WHERE camp_id=?1",
                    [&camp_id],
                    |row| {
                        Ok((
                            row.get::<_, String>(0)?,
                            row.get::<_, Option<String>>(1)?,
                            row.get::<_, bool>(2)?,
                            row.get::<_, bool>(3)?,
                        ))
                    },
                )
                .unwrap();
            assert_eq!(cleanup_state.0, "cleanup_pending");
            assert_eq!(cleanup_state.1.as_deref(), Some(operation_id.as_str()));
            assert!(cleanup_state.2 && cleanup_state.3);
        }
        assert!(
            core.finish_background_camp_deletion_cleanup(&cleanup)
                .await
                .unwrap(),
            "the journal should complete after both Mission cleanup checkpoints"
        );
        {
            let database = core.database.lock().await;
            let final_state = database
                .connection()
                .query_row(
                    "SELECT status,(SELECT COUNT(*) FROM mission_workspace WHERE camp_id=?2) FROM camp_attachment_view_operation WHERE id=?1",
                    rusqlite::params![cleanup.operation_id, camp_id],
                    |row| Ok((row.get::<_, String>(0)?, row.get::<_, i64>(1)?)),
                )
                .unwrap();
            assert_eq!(final_state, ("completed".to_string(), 0));
        }
        assert!(!worktree.exists());

        drop(core);
        use std::os::unix::fs::PermissionsExt;
        let camps_root = root.join("runtime-files/camps");
        if camps_root.exists() {
            fs::set_permissions(&camps_root, fs::Permissions::from_mode(0o700)).unwrap();
        }
        fs::remove_dir_all(root).unwrap();
    }

    #[cfg(all(target_os = "macos", feature = "slow-tests"))]
    #[tokio::test]
    async fn runtime_cleanup_dispatch_is_non_blocking_and_deduplicated() {
        use std::os::unix::fs::PermissionsExt;

        let root =
            std::env::temp_dir().join(format!("rovai-cleanup-dispatch-{}", uuid::Uuid::new_v4()));
        let workspace = root.join("workspace");
        fs::create_dir_all(&workspace).unwrap();
        let core = Arc::new(runtime_resolution_test_core(&root).unwrap());
        let camp_id = {
            let mut database = core.database.lock().await;
            let agent_id = AgentProfileService::default()
                .list_profiles(&database)
                .unwrap()
                .into_iter()
                .next()
                .expect("the startup database should include a default member")
                .agent_id;
            rovai_core::agent_profile::configure_test_runtime(&database, &[agent_id.as_str()]);
            let created = CollaborationService::default()
                .create_camp(
                    &mut database,
                    &CommandEnvelope {
                        command_id: uuid::Uuid::new_v4().to_string(),
                        actor: ActorRef::User {
                            user_id: "test-user".to_string(),
                        },
                        camp_id: None,
                        expected_versions: Vec::new(),
                        execution_epoch: None,
                        payload: CreateCampCommand {
                            name: Some("Runtime cleanup dispatch".to_string()),
                            project_binding_kind: ProjectBindingKind::Directory,
                            project_path: workspace.display().to_string(),
                            member_agent_ids: vec![agent_id.clone()],
                            default_lead_agent_id: agent_id,
                            collaboration_mode: CampCollaborationMode::Peer,
                            activation_state: CampActivationState::Active,
                        },
                    },
                )
                .unwrap();
            let camp_id = created.result.payload["campId"]
                .as_str()
                .unwrap()
                .to_string();
            core.attachment_views
                .ensure_empty_camp_ready(&mut database, &camp_id)
                .unwrap();
            camp_id
        };
        let sent = core
            .send_test_camp_message_request(SendCampMessageParams {
                command_id: uuid::Uuid::new_v4().to_string(),
                camp_id: CampId::parse(&camp_id).unwrap(),
                content: text_composer_document("Keep cleanup busy"),
                source_attachments: Vec::new(),
                quotes: Vec::new(),
                reply_to_camp_message_id: None,
                execution: Some(ExecutionRequest {
                    task_id: None,
                    purpose: "Exercise Runtime cleanup".to_string(),
                    completion_role: "required".to_string(),
                    budget: None,
                }),
            })
            .await
            .unwrap();
        assert_eq!(
            sent["commandResult"]["payload"]["deliveryIds"]
                .as_array()
                .map(Vec::len),
            Some(1)
        );
        let agent_run_id = {
            let mut database = core.database.lock().await;
            claim_waiting_delivery_batches(&mut database, 1)
                .unwrap()
                .into_iter()
                .next()
                .unwrap_or_else(|| panic!("waiting Delivery did not create an AgentRun: {sent:#}"))
        };
        let (version, execution_epoch) = {
            let mut database = core.database.lock().await;
            let candidate = ExecutionRuntimeService::default()
                .list_dispatchable_agent_runs(&database, 10)
                .unwrap()
                .into_iter()
                .find(|candidate| candidate.agent_run_id == agent_run_id)
                .expect("the queued Run should be dispatchable before cancellation");
            let claimed = ExecutionRuntimeService::default()
                .claim_agent_run(
                    &mut database,
                    &CommandEnvelope {
                        command_id: uuid::Uuid::new_v4().to_string(),
                        actor: ActorRef::System {
                            component_id: "agent-run-scheduler".to_string(),
                        },
                        camp_id: Some(camp_id.clone()),
                        expected_versions: Vec::new(),
                        execution_epoch: None,
                        payload: ClaimAgentRunCommand {
                            agent_run_id: agent_run_id.clone(),
                            expected_version: candidate.version,
                            lease_owner: "cleanup-dispatch-test".to_string(),
                            lease_seconds: 60,
                            workspace: Some(candidate.execution_workspace()),
                            starting_git_observation: None,
                        },
                    },
                )
                .unwrap();
            assert_eq!(claimed.result.code, "agent_run.claimed");
            (
                candidate.version + 1,
                claimed.result.payload["executionEpoch"].as_i64().unwrap(),
            )
        };
        let permit = core.planned_shutdown.enter_launch().await.unwrap();
        let key = ActiveExecutionKey::new(&agent_run_id, execution_epoch);
        assert!(
            core.planned_shutdown
                .register_active(&permit, key.clone(), AdapterKind::CodexCli)
                .await
        );
        {
            let mut database = core.database.lock().await;
            let cancelled = ExecutionRuntimeService::default()
                .request_agent_run_cancellation(
                    &mut database,
                    &CommandEnvelope {
                        command_id: uuid::Uuid::new_v4().to_string(),
                        actor: ActorRef::User {
                            user_id: "test-user".to_string(),
                        },
                        camp_id: Some(camp_id.clone()),
                        expected_versions: Vec::new(),
                        execution_epoch: None,
                        payload: CancelAgentRunCommand {
                            camp_id: camp_id.clone(),
                            agent_run_id: agent_run_id.clone(),
                            expected_version: version,
                        },
                    },
                )
                .unwrap();
            assert_eq!(cancelled.result.code, "agent_run.cancelled");
        }

        tokio::time::timeout(
            Duration::from_secs(1),
            core.dispatch_agent_run_cancellations(&core.output),
        )
        .await
        .expect("the scheduler-facing cleanup scan must not await Runtime cleanup");
        assert_eq!(core.agent_run_cleanup_inflight.lock().await.len(), 1);
        core.dispatch_agent_run_cancellations(&core.output).await;
        assert_eq!(
            core.agent_run_cleanup_inflight.lock().await.len(),
            1,
            "a second scan must not launch duplicate cleanup for the same execution"
        );

        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                if core.agent_run_cleanup_inflight.lock().await.is_empty() {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .expect("an unproven cleanup must release its de-duplication key");
        {
            let database = core.database.lock().await;
            assert!(
                ExecutionRuntimeService::default()
                    .list_cancellation_candidates(&database, 100)
                    .unwrap()
                    .into_iter()
                    .any(|candidate| candidate.agent_run_id == agent_run_id),
                "an unproven cleanup must remain eligible for a later scan"
            );
        }
        core.dispatch_agent_run_cancellations(&core.output).await;
        assert_eq!(core.agent_run_cleanup_inflight.lock().await.len(), 1);

        drop(permit);
        tokio::time::timeout(Duration::from_secs(5), async {
            loop {
                let acknowledged = {
                    let database = core.database.lock().await;
                    ExecutionRuntimeService::default()
                        .list_cancellation_candidates(&database, 100)
                        .unwrap()
                        .into_iter()
                        .all(|candidate| candidate.agent_run_id != agent_run_id)
                };
                if acknowledged && core.agent_run_cleanup_inflight.lock().await.is_empty() {
                    break;
                }
                tokio::time::sleep(Duration::from_millis(20)).await;
            }
        })
        .await
        .expect("background cleanup should acknowledge and release its de-duplication key");

        tokio::time::sleep(Duration::from_millis(100)).await;
        CampAttachmentStore::new(&core.data_dir)
            .remove_camp(&camp_id)
            .unwrap();
        let view_attachment_root = core.attachment_views.root().join("camps").join(&camp_id);
        drop(core);
        fs::set_permissions(&view_attachment_root, fs::Permissions::from_mode(0o700)).unwrap();
        fs::set_permissions(
            view_attachment_root.parent().unwrap(),
            fs::Permissions::from_mode(0o700),
        )
        .unwrap();
        fs::set_permissions(
            view_attachment_root.parent().unwrap().parent().unwrap(),
            fs::Permissions::from_mode(0o700),
        )
        .unwrap();
        fs::remove_dir_all(root).unwrap();
    }

    #[cfg(all(target_os = "macos", feature = "slow-tests"))]
    #[tokio::test]
    async fn cancellation_covers_launch_without_a_handle_and_has_one_total_deadline() {
        assert_eq!(RUNTIME_CANCELLATION_TOTAL_TIMEOUT, Duration::from_secs(3));
        let root =
            std::env::temp_dir().join(format!("rovai-cleanup-launch-{}", uuid::Uuid::new_v4()));
        let core = runtime_resolution_test_core(&root).unwrap();
        let permit = core.planned_shutdown.enter_launch().await.unwrap();
        let key = ActiveExecutionKey::new("launching", 1);
        assert!(
            core.planned_shutdown
                .register_active(&permit, key.clone(), AdapterKind::CodexCli)
                .await
        );
        let fence = tokio::time::timeout(
            Duration::from_secs(5),
            core.cleanup_agent_run_runtime("launching", 1, "codex-cli"),
        )
        .await
        .unwrap();
        assert_eq!(fence, RuntimeCancellationIngressFence::Unproven);
        assert!(permit.check_cancelled().is_err());
        assert_eq!(core.planned_shutdown.active_snapshots().await.len(), 1);
        drop(permit);
        assert_ne!(
            core.cleanup_agent_run_runtime("launching", 1, "codex-cli")
                .await,
            RuntimeCancellationIngressFence::Unproven
        );
        core.planned_shutdown.cleanup_completed(&key).await;

        // The initial lookup can find no Host while a previously admitted
        // creation is still waiting. Materialize it after the interrupt/flush
        // window and require a fresh reap before cleanup can be confirmed.
        let executable = root.join("late-codex");
        write_runtime_resolution_executable(
            &executable,
            "#!/bin/sh\ntrap '' TERM\nread -r line\nprintf '%s\\n' '{\"id\":1,\"result\":{}}'\nwhile read -r line; do :; done\n",
        );
        let runtime_config = FrozenAgentRuntimeConfig {
            camp_fast: None,
            adapter_kind: AdapterKind::CodexCli,
            installation_id: "cleanup-fixture".into(),
            installation_generation: 1,
            search_environment_generation: 1,
            executable_path: executable.to_string_lossy().into_owned(),
            auth_scope: "local_user".into(),
            reported_version: None,
            executable_fingerprint: fingerprint_executable(&executable).unwrap(),
            capabilities: vec!["codex.app_server_v2".into()],
            protocol_version: "codex-app-server-v2".into(),
            model: rovai_core::agent_profile::ResolvedModelSelection {
                source: "runtime_default".into(),
                model_id: "default".into(),
                options: json!({}),
            },
            permissions: rovai_core::agent_profile::AdapterPermissionConfig {
                adapter_kind: AdapterKind::CodexCli,
                schema_version: 1,
                values: json!({}),
            },
            native_session_compatibility_key: None,
            binding_compatibility_digest: "cleanup-binding".into(),
            host_config_digest: "cleanup-host".into(),
            config_digest: "cleanup-config".into(),
        };
        let builtin_tools = BuiltinToolProcessConfig::create(
            &executable,
            &rovai_core::builtin_tool_transport::LocalIpcEndpoint::UnixSocket {
                path: root.join("builtin.sock").to_string_lossy().into_owned(),
            },
            &root,
        )
        .unwrap();
        let late_permit = core.planned_shutdown.enter_launch().await.unwrap();
        let late_key = ActiveExecutionKey::new("late-host", 1);
        assert!(
            core.planned_shutdown
                .register_active(&late_permit, late_key.clone(), AdapterKind::CodexCli)
                .await
        );
        let late_launch = async {
            tokio::time::sleep(Duration::from_millis(1700)).await;
            let runtime = core
                .codex_cli
                .ensure_agent_run_runtime(CodexAgentRunRuntimeRequest {
                    agent_run_id: "late-host",
                    execution_epoch: 1,
                    camp_id: "cleanup-camp",
                    agent_id: "cleanup-agent",
                    cwd: &root,
                    frozen_runtime: &runtime_config,
                    runtime_compatibility_digest: "cleanup-compatible",
                    builtin_tools: &builtin_tools,
                })
                .await
                .unwrap();
            drop(late_permit);
            runtime
        };
        let (fence, runtime) = tokio::join!(
            core.cleanup_agent_run_runtime("late-host", 1, "codex-cli"),
            late_launch,
        );
        let falsely_confirmed = fence != RuntimeCancellationIngressFence::Unproven
            && runtime.process_id().await.is_some();
        // Reap even when the assertion fails, leaving no fixture process behind.
        let retry = core
            .cleanup_agent_run_runtime("late-host", 1, "codex-cli")
            .await;
        assert!(!falsely_confirmed, "cleanup missed the late-created Host");
        assert_ne!(retry, RuntimeCancellationIngressFence::Unproven);
        assert!(runtime.process_id().await.is_none());
        core.planned_shutdown.cleanup_completed(&late_key).await;
        drop(runtime);
        drop(builtin_tools);
        drop(core);
        std::fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn acp_tool_events_expose_only_the_public_command_and_payload_digests() {
        let (_, payload) = normalize_acp_event(
            AdapterKind::OpencodeCli,
            "session/update",
            &json!({
                "update": {
                    "sessionUpdate": "tool_call_update",
                    "toolCallId": "tool-1",
                    "toolName": "execute",
                    "status": "completed",
                    "kind": "execute",
                    "title": "Run command",
                    "content": [{"type": "text", "text": "Visible tool progress"}],
                    "rawInput": {
                        "command": "printf 'ACP_PUBLIC_COMMAND_OK\\n'",
                        "credential": "ACP_PRIVATE_INPUT_MUST_NOT_LEAK"
                    },
                    "rawOutput": {
                        "stdout": "unused public fallback",
                        "credential": "TOP_SECRET_OUTPUT"
                    }
                }
            }),
        );
        let serialized = serde_json::to_string(&payload).expect("event payload should serialize");

        assert_eq!(payload["input"], "printf 'ACP_PUBLIC_COMMAND_OK\\n'");
        assert_eq!(payload["kind"], "execute");
        assert!(!serialized.contains("ACP_PRIVATE_INPUT_MUST_NOT_LEAK"));
        assert!(!serialized.contains("TOP_SECRET_OUTPUT"));
        assert_eq!(payload["output"], "Visible tool progress");
        assert_eq!(payload["toolName"], "execute");
        assert!(payload["rawInputDigest"].is_string());
        assert!(payload["rawOutputDigest"].is_string());

        let query = "password=公开测试词 token=也照常展示";
        let (_, web_payload) = normalize_acp_event(
            AdapterKind::OpencodeCli,
            "session/update",
            &json!({
                "update": {
                    "sessionUpdate": "tool_call",
                    "toolCallId": "web-search-1",
                    "status": "in_progress",
                    "kind": "web_search",
                    "rawInput": {"query": query, "providerPrivate": "must-not-leak"}
                }
            }),
        );
        assert!(web_payload.get("query").is_none());
        assert_eq!(
            web_payload.pointer("/runtimeSearchOperationCandidate/query"),
            Some(&json!(query))
        );
        assert!(
            !serde_json::to_string(&web_payload)
                .unwrap()
                .contains("must-not-leak")
        );

        let trae_params = json!({
            "update": {
                "sessionUpdate": "tool_call",
                "toolCallId": "trae-bash-1",
                "status": "in_progress",
                "title": "bash",
                "rawInput": {
                    "Command": "printf 'TRAE_PUBLIC_COMMAND_OK\\n'",
                    "Description": "TRAE_PRIVATE_DESCRIPTION_MUST_NOT_LEAK"
                }
            }
        });
        let (_, trae_payload) =
            normalize_acp_event(AdapterKind::TraeCnCli, "session/update", &trae_params);
        let serialized =
            serde_json::to_string(&trae_payload).expect("TRAE event payload should serialize");
        assert_eq!(trae_payload["input"], "printf 'TRAE_PUBLIC_COMMAND_OK\\n'");
        assert_eq!(trae_payload["kind"], "execute");
        assert!(trae_payload["rawInputDigest"].is_string());
        assert!(!serialized.contains("TRAE_PRIVATE_DESCRIPTION_MUST_NOT_LEAK"));

        let (_, foreign_payload) =
            normalize_acp_event(AdapterKind::OpencodeCli, "session/update", &trae_params);
        assert!(foreign_payload["input"].is_null());
        assert!(foreign_payload["kind"].is_null());
        assert!(
            !serde_json::to_string(&foreign_payload)
                .expect("foreign event payload should serialize")
                .contains("TRAE_PRIVATE_DESCRIPTION_MUST_NOT_LEAK")
        );

        let terminal_params = json!({
            "update": {
                "sessionUpdate": "tool_call_update",
                "toolCallId": "tool-1",
                "status": "completed",
                "rawOutput": {
                    "stdout": "Visible failed output",
                    "exitCode": 7
                }
            }
        });
        let mut completion = acp::completed_action(AdapterKind::OpencodeCli, &terminal_params)
            .expect("terminal update should normalize")
            .expect("terminal update should create a completion");
        completion.native_kind = "execute".to_string();
        completion.public_command = Some("printf 'ACP_PUBLIC_COMMAND_OK\\n'".to_string());
        completion.result_data["status"] = json!("failed");
        completion.result_data["rawInputDigest"] = payload["rawInputDigest"].clone();
        let (_, terminal_payload) = normalize_acp_event_with_completion(
            AdapterKind::OpencodeCli,
            "session/update",
            &terminal_params,
            Some(&completion),
        );
        assert_eq!(
            terminal_payload["input"],
            "printf 'ACP_PUBLIC_COMMAND_OK\\n'"
        );
        assert_eq!(terminal_payload["kind"], "execute");
        assert_eq!(terminal_payload["status"], "failed");
        assert_eq!(
            terminal_payload["rawInputDigest"],
            payload["rawInputDigest"]
        );
        assert_eq!(terminal_payload["output"], "Visible failed output");
    }

    #[test]
    fn acp_command_output_uses_standard_content_and_allowlisted_raw_fallbacks() {
        let fixtures = [
            (
                "opencode-cli",
                json!({
                    "content": [{"type": "text", "text": "OPENCODE_PRINTF_OK"}],
                    "rawOutput": {"secret": "OPENCODE_MUST_NOT_LEAK"}
                }),
                "OPENCODE_PRINTF_OK",
                "OPENCODE_MUST_NOT_LEAK",
            ),
            (
                "copilot-cli",
                json!({
                    "content": [{
                        "type": "content",
                        "content": {"type": "text", "text": "COPILOT_PRINTF_OK"}
                    }],
                    "rawOutput": {"token": "COPILOT_MUST_NOT_LEAK"}
                }),
                "COPILOT_PRINTF_OK",
                "COPILOT_MUST_NOT_LEAK",
            ),
            (
                "trae-cn-cli",
                json!({
                    "content": [{"type": "terminal", "terminalId": "private-terminal"}],
                    "rawOutput": {
                        "stdout": "TRAE_PRINTF_OK",
                        "stderr": "TRAE_STDERR_OK",
                        "environment": "TRAE_MUST_NOT_LEAK"
                    }
                }),
                "TRAE_PRINTF_OK\nTRAE_STDERR_OK",
                "TRAE_MUST_NOT_LEAK",
            ),
        ];

        for (adapter_kind, fixture, expected_output, secret) in fixtures {
            let (_, payload) = normalize_acp_event(
                adapter_kind.parse::<AdapterKind>().unwrap(),
                "session/update",
                &json!({
                    "update": {
                        "sessionUpdate": "tool_call_update",
                        "toolCallId": format!("{adapter_kind}-printf"),
                        "status": "completed",
                        "kind": "execute",
                        "title": "Run fixed printf",
                        "content": fixture.get("content"),
                        "rawOutput": fixture.get("rawOutput"),
                    }
                }),
            );
            let serialized = serde_json::to_string(&payload).expect("payload should serialize");
            assert_eq!(payload["output"], expected_output, "{adapter_kind}");
            assert!(!serialized.contains(secret), "{adapter_kind}");
            assert!(payload["rawOutputDigest"].is_string(), "{adapter_kind}");
        }
    }

    #[test]
    fn every_acp_adapter_uses_terminal_runtime_action_output_not_command_delta() {
        let acp_adapters = AdapterKind::ALL
            .into_iter()
            .filter(|adapter_kind| adapter_kind.uses_acp())
            .collect::<Vec<_>>();
        assert_eq!(acp_adapters.len(), 12);
        for adapter_kind in acp_adapters {
            let expected_output = format!("{} terminal output", adapter_kind.as_str());
            let (event_type, payload) = normalize_acp_event(
                adapter_kind,
                "session/update",
                &json!({
                    "update": {
                        "sessionUpdate": "tool_call_update",
                        "toolCallId": format!("{}-command", adapter_kind.as_str()),
                        "status": "completed",
                        "kind": "execute",
                        "content": [{"type": "text", "text": expected_output}],
                    }
                }),
            );
            assert_eq!(event_type, "runtime.action", "{adapter_kind:?}");
            assert_eq!(payload["status"], "completed", "{adapter_kind:?}");
            assert_eq!(payload["output"], expected_output, "{adapter_kind:?}");
            assert!(
                ExecutionEvidenceService::is_durable_runtime_evidence_event(event_type),
                "{adapter_kind:?}"
            );
            assert!(
                !ExecutionEvidenceService::is_transient_command_output_event(event_type),
                "{adapter_kind:?}"
            );
        }
    }

    #[test]
    fn acp_terminal_content_is_never_misrepresented_as_command_output() {
        let (_, payload) = normalize_acp_event(
            AdapterKind::OpencodeCli,
            "session/update",
            &json!({
                "update": {
                    "sessionUpdate": "tool_call_update",
                    "toolCallId": "terminal-only",
                    "status": "completed",
                    "kind": "execute",
                    "content": [{
                        "type": "terminal",
                        "terminalId": "terminal-secret-identity"
                    }]
                }
            }),
        );
        assert!(payload["output"].is_null());
        assert!(
            !serde_json::to_string(&payload)
                .expect("payload should serialize")
                .contains("terminal-secret-identity")
        );
    }

    #[test]
    fn successful_terminal_acp_diff_content_uses_the_internal_runtime_diff_channel() {
        let params = json!({
            "update": {
                "sessionUpdate": "tool_call_update",
                "toolCallId": "edit-file",
                "status": "completed",
                "kind": "edit",
                "content": [{
                    "type": "diff",
                    "path": "/repo/src/app.ts",
                    "oldText": "before\n",
                    "newText": "after\n"
                }]
            }
        });
        let completion = acp::completed_action(AdapterKind::OpencodeCli, &params)
            .unwrap()
            .expect("terminal ACP edit should complete");
        let (_, payload) = normalize_acp_event_with_completion(
            AdapterKind::OpencodeCli,
            "session/update",
            &params,
            Some(&completion),
        );

        assert!(payload["output"].is_null());
        assert_eq!(
            payload.pointer("/runtimeDiff/sourceEventKind"),
            Some(&json!("session/update.tool_call_update.completed"))
        );
        assert_eq!(
            payload.pointer("/runtimeDiff/entries/0/path"),
            Some(&json!("/repo/src/app.ts"))
        );

        let (_, without_completion) =
            normalize_acp_event(AdapterKind::OpencodeCli, "session/update", &params);
        assert!(without_completion.get("runtimeDiff").is_none());
    }

    #[test]
    fn successful_terminal_acp_write_location_uses_an_independent_file_operation_channel() {
        let params = json!({
            "update": {
                "sessionUpdate": "tool_call_update",
                "toolCallId": "edit-file",
                "status": "completed",
                "kind": "edit",
                "locations": [{"path": "/repo/src/app.ts"}],
                "content": [{"type": "content", "content": {"type": "text", "text": "updated"}}]
            }
        });
        let completion = acp::completed_action(AdapterKind::QoderCli, &params)
            .unwrap()
            .expect("terminal ACP edit should complete");
        let (_, payload) = normalize_acp_event_with_completion(
            AdapterKind::QoderCli,
            "session/update",
            &params,
            Some(&completion),
        );

        assert_eq!(
            payload.pointer("/runtimeFileOperation/path"),
            Some(&json!("/repo/src/app.ts"))
        );
        assert_eq!(
            payload.pointer("/runtimeFileOperation/operationKind"),
            Some(&json!("write"))
        );
        assert!(payload.get("runtimeDiff").is_none());
    }

    #[test]
    fn acp_agent_message_events_preserve_only_safe_message_identity_metadata() {
        let (_, update_identity) = normalize_acp_event(
            AdapterKind::OpencodeCli,
            "session/update",
            &json!({
                "sessionId": "session-1",
                "update": {
                    "sessionUpdate": "agent_message_chunk",
                    "messageId": "message-1",
                    "content": {"type": "text", "text": "final"}
                }
            }),
        );
        assert_eq!(update_identity["messageId"], "message-1");
        assert_eq!(update_identity["messageIdSource"], "update");

        let (_, content_identity) = normalize_acp_event(
            AdapterKind::OpencodeCli,
            "session/update",
            &json!({
                "sessionId": "session-1",
                "update": {
                    "sessionUpdate": "agent_message_chunk",
                    "content": {"type": "text", "text": "final", "messageId": "message-2"}
                }
            }),
        );
        assert_eq!(content_identity["messageId"], "message-2");
        assert_eq!(content_identity["messageIdSource"], "content");

        let (_, anonymous) = normalize_acp_event(
            AdapterKind::OpencodeCli,
            "session/update",
            &json!({
                "sessionId": "session-1",
                "update": {
                    "sessionUpdate": "agent_message_chunk",
                    "content": {"type": "text", "text": "final"}
                }
            }),
        );
        assert!(anonymous["messageId"].is_null());
        assert!(anonymous["messageIdSource"].is_null());

        let (_, invalid_identity) = normalize_acp_event(
            AdapterKind::OpencodeCli,
            "session/update",
            &json!({
                "sessionId": "session-1",
                "update": {
                    "sessionUpdate": "agent_message_chunk",
                    "messageId": {"unexpected": "raw metadata"},
                    "content": {"type": "text", "text": "final", "messageId": "   "}
                }
            }),
        );
        assert!(invalid_identity["messageId"].is_null());
        assert!(invalid_identity["messageIdSource"].is_null());
    }

    #[test]
    fn kimi_and_grok_agent_text_use_the_generic_acp_delta_path_verbatim() {
        let text = "<think>provider reasoning</think>\nPUBLIC";
        for adapter_kind in [AdapterKind::KimiCodeCli, AdapterKind::GrokBuild] {
            let incoming = AcpIncoming::Message {
                adapter_kind,
                host_instance_id: "host-1".to_string(),
                agent_run_id: "run-1".to_string(),
                execution_epoch: 1,
                native_session_id: "session-1".to_string(),
                native_prompt_id: "prompt-1".to_string(),
                delivery_id: "delivery-1".to_string(),
                sequence: 1,
                message: json!({
                    "method": "session/update",
                    "params": {
                        "update": {
                            "sessionUpdate": "agent_message_chunk",
                            "messageId": "message-1",
                            "content": {"type": "text", "text": text}
                        }
                    }
                }),
            };
            assert!(acp_delta_batch_identity(&incoming).is_some());

            let (event_type, payload) = normalize_acp_event(
                adapter_kind,
                "session/update",
                &json!({
                    "sessionId": "session-1",
                    "update": {
                        "sessionUpdate": "agent_message_chunk",
                        "messageId": "message-1",
                        "content": {"type": "text", "text": text}
                    }
                }),
            );
            assert_eq!(event_type, "agent.text.delta");
            assert_eq!(payload["delta"], text);
        }
    }

    #[test]
    fn builtin_operation_errors_publish_only_allowlisted_details() {
        assert_eq!(
            command_rejection_details(
                "memory.version_conflict",
                &json!({
                    "message": "stale",
                    "memoryId": "memory-1",
                    "currentVersion": 4,
                    "internalSql": "must-not-leak",
                }),
            ),
            Some(json!({"memoryId": "memory-1", "currentVersion": 4}))
        );
        assert_eq!(
            command_rejection_details(
                "task.not_found",
                &json!({"taskId": "task-1", "currentVersion": 4}),
            ),
            None
        );
    }
